,p_plug_display_sequence=>20
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- SELECT a.ID,',
'--        a.ASSET_TAG,',
'--        a.ASSET_NAME,',
'--        c.CATEGORY_NAME,',
'--        (SELECT u.FIRSTNAME || '' '' || u.LASTNAME AS NAME',
'--           FROM TRN_ASSET_ASSIGNMENT t',
'--           JOIN HR_EMPLOYEE u ON u.ID = t.EMPLOYEE_ID',
'--          WHERE t.ASSET_ID = a.ID',
'--            AND t.STATUS = ''ACTIVE'') AS ASSIGNED_TO,',
'--        a.STATUS,',
'--        CASE UPPER(a.STATUS)',
'--            WHEN ''AVAILABLE'' THEN ''background-color: #e6f4ea; color: #137333;''',
'--            WHEN ''ASSIGNED''  THEN ''background-color: #e8f0fe; color: #1a73e8;''',
'--            ELSE ''background-color: #f1f3f4; color: #5f6368;''',
'--        END AS STATUS_STYLE,',
'--        ai.INVOICE_NO',
'--   FROM MST_ASSET a',
'--   JOIN MST_ASSET_CATEGORY c ON c.ID = a.CATEGORY_ID',
'--   LEFT JOIN MST_ASSET_INVOICE ai ON ai.ID = a.INVOICE_ID',
'',
'',
'',
'SELECT a.ID,',
'       a.ASSET_TAG,',
'       a.ASSET_NAME,',
'       c.CATEGORY_NAME,',
'       (SELECT u.FIRSTNAME || '' '' || u.LASTNAME AS NAME',
'          FROM TRN_ASSET_ASSIGNMENT t',
'          JOIN HR_EMPLOYEE u ON u.ID = t.EMPLOYEE_ID',
'         WHERE t.ASSET_ID = a.ID',
'           AND t.STATUS = ''ACTIVE'') AS ASSIGNED_TO,',
'       a.STATUS,',
'',
'       CASE UPPER(a.STATUS)',
'           WHEN ''AVAILABLE'' THEN ''background-color: #e6f4ea; color: #137333;''',
'           WHEN ''ASSIGNED''  THEN ''background-color: #e8f0fe; color: #1a73e8;''',
'           ELSE ''background-color: #f1f3f4; color: #5f6368;''',
'       END AS STATUS_STYLE,',
'',
'       CASE UPPER(a.STATUS)',
'           WHEN ''AVAILABLE'' THEN',
'             ''<a href="'' || apex_util.prepare_url(',
'               ''f?p='' || :APP_ID || '':3:'' || :APP_SESSION || ''::NO:3:P3_ASSET_ID:'' || a.ID',
'             ) || ''" class="t-Button t-Button--small t-Button--icon" style="background-color:#e6f4ea; color:#137333; border-color:#b7e1c3; width: 90px; text-align: center;">Assign</a>''',
'           WHEN ''ASSIGNED'' THEN',
'             ''<a href="'' || apex_util.prepare_url(',
'               ''f?p='' || :APP_ID || '':9:'' || :APP_SESSION || ''::NO:9:P9_ASSET_ID:'' || a.ID',
'             ) || ''" class="t-Button t-Button--small t-Button--icon" style="background-color:#fce8e6; color:#c5221f; border-color:#f4b8b3; width: 90px; text-align: center;">Unassign</a>''',
'           ELSE NULL',
'       END AS ACTION_BTN,',
'',
'       ''<span class="fa fa-history"></span>'' AS TIME_LINE',
'',
'  FROM MST_ASSET a',
'  JOIN MST_ASSET_CATEGORY c ON c.ID = a.CATEGORY_ID',
'WHERE (:P2_STATUS_FILTER IS NULL OR a.STATUS = :P2_STATUS_FILTER)',
''))
