wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(18152827887650635)
,p_plug_name=>'Asset Inventory'
,p_static_id=>'assigned_tab'
,p_title=>'Assignd Assets'
,p_parent_plug_id=>wwv_flow_imp.id(18154140205650648)
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>40
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- SELECT a.ID,',
'--        a.ASSET_TAG,',
'--        a.ASSET_NAME,',
'--        c.CATEGORY_NAME,',
'--        (SELECT u.FIRSTNAME || '' '' || u.LASTNAME AS NAME',
'--           FROM TRN_ASSET_ASSIGNMENT t',
'--           JOIN HR_EMPLOYEE u ON u.ID = t.EMPLOYEE_ID',
'--          WHERE t.ASSET_ID = a.ID',
'--            AND t.STATUS = ''ACTIVE'') AS ASSIGNED_TO,',
'--        a.STATUS,',
'--        CASE UPPER(a.STATUS)',
'--            WHEN ''AVAILABLE'' THEN ''background-color: #e6f4ea; color: #137333;''',
'--            WHEN ''ASSIGNED''  THEN ''background-color: #e8f0fe; color: #1a73e8;''',
'--            ELSE ''background-color: #f1f3f4; color: #5f6368;''',
'--        END AS STATUS_STYLE,',
'--        ai.INVOICE_NO',
'--   FROM MST_ASSET a',
'--   JOIN MST_ASSET_CATEGORY c ON c.ID = a.CATEGORY_ID',
'--   LEFT JOIN MST_ASSET_INVOICE ai ON ai.ID = a.INVOICE_ID',
'',
'',
'SELECT a.ID,',
'       a.ASSET_TAG,',
'       a.ASSET_NAME,',
'       c.CATEGORY_NAME,',
'       (SELECT u.FIRSTNAME || '' '' || u.LASTNAME AS NAME',
'          FROM TRN_ASSET_ASSIGNMENT t',
'          JOIN HR_EMPLOYEE u ON u.ID = t.EMPLOYEE_ID',
'         WHERE t.ASSET_ID = a.ID',
'           AND t.STATUS = ''ACTIVE'') AS ASSIGNED_TO,',
'       a.STATUS,',
'       ',
'       -- 1. Generates the badge colors based on Status',
'       CASE UPPER(a.STATUS)',
'           WHEN ''AVAILABLE'' THEN ''background-color: #e6f4ea; color: #137333;''',
'           WHEN ''ASSIGNED''  THEN ''background-color: #e8f0fe; color: #1a73e8;''',
'           ELSE ''background-color: #f1f3f4; color: #5f6368;''',
'       END AS STATUS_STYLE,',
'       ',
'       -- 2. Conditional labels for buttons (APEX hides the button if text is NULL)',
'       CASE UPPER(a.STATUS) WHEN ''AVAILABLE'' THEN ''Assign'' ELSE NULL END AS ASSIGN_LBL,',
'       CASE UPPER(a.STATUS) WHEN ''AVAILABLE'' THEN ''Remove'' ELSE NULL END AS REMOVE_LBL,',
'       CASE UPPER(a.STATUS) WHEN ''ASSIGNED''  THEN ''Unassign'' ELSE NULL END AS UNASSIGN_LBL,',
'       ''<span class="fa fa-history"></span>'' AS TIME_LINE',
'       ',
'    --    ai.INVOICE_NO',
'  FROM MST_ASSET a',
'  JOIN MST_ASSET_CATEGORY c ON c.ID = a.CATEGORY_ID',
'  WHERE a.STATUS = ''ASSIGNED''',
''))
