,p_event_id=>wwv_flow_imp.id(17763098940459004)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_static_id=>'native-set-value'
,p_action=>'NATIVE_SET_VALUE'
,p_affected_elements_type=>'ITEM'
,p_affected_elements=>'P6_ASSET_TAG'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'escape_special_characters', 'Y',
  'items_to_submit', 'P6_CATEGORY_ID',
  'plsql_function_body', wwv_flow_string.join(wwv_flow_t_varchar2(
    'DECLARE',
    '    v_category_name VARCHAR2(100);',
    '    v_short_code    VARCHAR2(10);',
    '    v_next_id       NUMBER;',
    'BEGIN',
    '    -- If the user clears the category dropdown, clear the tag',
    '    IF :P6_CATEGORY_ID IS NULL THEN',
    '        RETURN NULL;',
    '    END IF;',
    '',
    ' ',
    '    BEGIN',
    '        SELECT CATEGORY_NAME ',
    '        INTO v_category_name',
    '        FROM MST_ASSET_CATEGORY',
    '        WHERE ID = :P6_CATEGORY_ID;',
    '    EXCEPTION',
    '        WHEN NO_DATA_FOUND THEN',
    '            v_category_name := ''UNKNOWN'';',
    '    END;',
    '',
    ' ',
    '    v_short_code := UPPER(SUBSTR(v_category_name, 1, 3));',
    '',
    '    SELECT NVL(MAX(ID), 0) + 1 ',
    '    INTO v_next_id ',
    '    FROM MST_ASSET;',
    '',
    '    RETURN ''IT-'' || v_short_code || ''-'' || v_next_id;',
    'END;')),
  'suppress_change_event', 'N',
  'type', 'FUNCTION_BODY')).to_clob
,p_wait_for_result=>'Y'
,p_created_on=>wwv_flow_imp.dz('20260910104744Z')
,p_updated_on=>wwv_flow_imp.dz('20260910104744Z')
