'DECLARE',
'    v_status  VARCHAR2(20);',
'    v_message VARCHAR2(500);',
'BEGIN',
'    PKG_ASSET_ASSIGNMENT.SP_UNASSIGN_ASSET_V1(',
'        p_asset_id      => :P9_ASSET_ID,',
'        p_unassigned_by => :APP_USER,',
'        p_remarks       => :P9_REMARKS,',
'        p_out_status    => v_status,',
'        p_out_message   => v_message',
'    );',
'    IF v_status = ''ERROR'' THEN',
'        apex_error.add_error(',
'            p_message          => v_message,',
'            p_display_location => apex_error.c_inline_in_notification',
'        );',
'    ELSE',
'        apex_application.g_print_success_message := v_message;',
