wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(18104845667952696)
,p_plug_name=>'Assignment History'
,p_static_id=>'assignment-history'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT t.ID,',
'       a.ASSET_TAG,',
'       u.FIRSTNAME || '' '' || u.LASTNAME AS employee_name,',
'       t.ASSIGNED_DATE,',
'       t.UNASSIGNED_DATE,',
'       t.STATUS,',
'       CASE UPPER(t.STATUS)',
'           WHEN ''ACTIVE'' THEN ''t-Badge--info''   ',
'           WHEN ''RETURNED'' THEN ''t-Badge--basic'' ',
'           ELSE ''t-Badge--default''',
'       END AS status_class,',
'       t.REMARKS',
'  FROM TRN_ASSET_ASSIGNMENT t',
'  JOIN MST_ASSET a  ON a.ID = t.ASSET_ID',
'  JOIN "HRDEPT"."HR_EMPLOYEE" u  ON u.ID = t.EMPLOYEE_ID',
' ORDER BY t.ASSIGNED_DATE DESC'))
,p_plug_source_type=>'NATIVE_IR'
