,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT a.ASSET_NAME,',
'       ac.CATEGORY_NAME,',
'       COUNT(*) AS ASSET_COUNT',
'  FROM MST_ASSET a',
'  JOIN MST_ASSET_CATEGORY ac ON a.CATEGORY_ID = ac.ID',
' WHERE (:P14_STATUS IS NULL OR a.STATUS = :P14_STATUS)',
' GROUP BY a.ASSET_NAME, ac.CATEGORY_NAME',
' ORDER BY a.ASSET_NAME'))
,p_plug_source_type=>'NATIVE_IR'
