'  FROM TRN_ASSET_ASSIGNMENT t',
'  JOIN MST_ASSET a       ON a.ID = t.ASSET_ID',
'  JOIN HR_EMPLOYEE e     ON e.ID = t.EMPLOYEE_ID',
'  JOIN MST_ASSET_CATEGORY f ON f.ID = a.CATEGORY_ID',
' WHERE t.STATUS = ''ACTIVE''',
' AND (:P14_SELECT_EMPLOYEE IS NULL OR e.EMPNO = :P14_SELECT_EMPLOYEE)',
' ORDER BY EMPLOYEE, a.ASSET_NAME'))
,p_plug_source_type=>'NATIVE_IR'
